/*
Author: Adam Santone, PhD
Date: 2024
Notes:
 - Created with help from StarChat2 AI:
 - https://huggingface.co/spaces/HuggingFaceH4/starchat2-playground
*/

// Set initial configuration values
var pointCount = 100;
var strokeWeightValue = 2;
var colorValue = [245, 150, 50]; // RGB format
var maxConnectionDist = 120;

// Create an empty array to hold our Points
var points = [];

function setup() {
  //canvas description for screen readers
  describe('A series of moving particles that collide with walls and form an ever-changing network with nearby particles.');  

	// Setup canvas size
    createCanvas(windowWidth, windowHeight);

    // Set stroke properties
    strokeWeight(strokeWeightValue);
    stroke(colorValue[0], colorValue[1], colorValue[2]);

    // Populate our points array
    initializePoints();
}

function draw() {
    background(255);

    updateAndDisplayPoints();
    drawConnections();
}

// Function to generate random points
function initializePoints(){
    for (var i=0; i<pointCount; i++) {
        var tempX = Math.floor(Math.random()*width/2);
        var tempY = Math.floor(Math.random()*height/2);

        // Push a new object into the array with x & y properties
        points.push({x : tempX, y : tempY, 
                      vx : Math.random(2,5) * 2,
                      vy : Math.random(2,5) * 2});
    }
}

// Function to move the points and handle boundary collisions
function updateAndDisplayPoints(){
    for (var i=0; i<points.length; i++){
        var p = points[i];

        p.x += p.vx;
        p.y += p.vy;

        // Check for collision with boundaries
        if((p.x<=0||p.x>=width)){  
            p.vx*=-1;  
        }
        if((p.y<=0||p.y>=height)){  
            p.vy*=-1;  
        }

        // Display the point
        point(p.x, p.y);  
    }  
}

// Function to find connecting points based on proximity
function drawConnections(){
    for (var i=0; i<points.length; i++){
        var currentPoint = points[i];

        for (var j=i+1; j<points.length; j++){
            var nextPoint = points[j];

            // Calculate squared euclidean distance
            var dx = currentPoint.x-nextPoint.x;
            var dy = currentPoint.y-nextPoint.y;
            var sqrDist = dx*dx + dy*dy;

            // Draw connection if below max distance threshold
            if(sqrDist<(maxConnectionDist*maxConnectionDist)){
                line(currentPoint.x, currentPoint.y, 
                     nextPoint.x, nextPoint.y);
            }
        }
    }
}

